import {bankSet} from './ramp-banks.js';
import {HybridRenderer} from './hybrid-renderer.js';import {buildWorld} from './hybrid-world.js';import {CliffMapScene} from './cliff-map-scene.js';import {rampInfo} from './cliff-ramps.js';
const hybrid=new HybridRenderer(),cliffs=new CliffMapScene(hybrid.scene),{renderer,camera,scene}=hybrid;document.querySelector('#scene').append(renderer.domElement);renderer.setSize(900,600);renderer.setPixelRatio(devicePixelRatio);
function render(){renderer.render(scene,camera);}
function update(){const direction=document.querySelector('#direction').value,map={terrain:Array.from({length:38},()=>Array(38).fill('ground-grass')),props:[],upper:[{},{}],stairs:[],edges:{}};
 for(const [i,surface]of ['grass','sand','road','concrete'].entries()){const p={x:5+i*8,y:9,z:0,kind:'ramp-'+surface+'-'+direction},r=rampInfo(p);map.props.push(...bankSet(p,surface==='sand'?'sand':'dirt'),p,{x:r.exit.x,y:r.exit.y,z:0,kind:'cliff-ledge',cliffMask:15,cliffSand:surface==='sand'?1:0});map.upper[0][r.exit.x+','+r.exit.y]='floor';for(const side of [-1,1])for(let step=0;step<5;step++){const x=r.low.x+r.dx*step-r.dy*side*2,y=r.low.y+r.dy*step+r.dx*side*2;map.props.push({x,y,z:0,kind:'cliff-ledge',cliffMask:15,cliffSand:surface==='sand'?1:0});}for(const side of [-1,1])map.props.push({x:r.exit.x-r.dy*side,y:r.exit.y+r.dx*side,z:0,kind:'cliff-ledge',cliffMask:15,cliffSand:surface==='sand'?1:0});}
 hybrid.rebuild(buildWorld(map),null,1,map);cliffs.rebuild(map,1,{editor:true});camera.left=-19;camera.right=19;camera.top=12.666;camera.bottom=-12.666;camera.near=.1;camera.far=100;camera.position.set(32,25,34);camera.lookAt(19,0,10);camera.updateProjectionMatrix();render();document.querySelector('#status').textContent=direction+' uphill · grass / sand / asphalt / concrete';window.rampStudy={hybrid,map,render,update};}
hybrid.onReady=render;document.querySelector('#direction').onchange=update;update();
